arguments.command:
cd /app/data/_ops; cat > /tmp/an.py <<'EOF'
import re,json,sys
d=sys.argv[1]
com={}
for l in open(d+'/commits.jsonl'):
    j=json.loads(l); com[j['txn']]=j
runs={}
for l in open(d+'/scheduler.log'):
    ts,job,run,rest=l.rstrip('\n').split(' ',3)
    r=runs.setdefault((job,run),{'ev':[]})
    r['ev'].append((ts,rest))
    m=re.search(r'ordered_at >= (\S+) and ordered_at < (\S+): (\d+) rows; sent txn (\d+) to commit into (\S+)',rest)
    if m: r['rng']=(m[1],m[2]); r['txn']=int(m[4]); r['tbl']=m[5]; r['n']=int(m[3])
    m=re.search(r'state=(\w+)',rest)
    if m: r['state']=m[1]
for (job,run),r in runs.items():
    if job in sys.argv[2:] and 'txn' in r:
        c=com[r['txn']]
        print(job,run,r['rng'],r['n'],r['tbl'],r['state'],c['outcome'],c['at'],c['rows'])
EOF
python3 /tmp/an.py . legacy_orders | awk '{print $6,$7}' | sort | uniq -c; python3 /tmp/an.py . orders_hourly | awk '{print $6,$7}' | sort | uniq -c

